fun maxSlidingWindow(nums: IntArray, k: Int): IntArray {
    val result = IntArray(nums.size - k + 1)
    val dq = ArrayDeque<Int>()                     // indices, values decreasing
    for (i in nums.indices) {
        // 1. remove the front if it is out of the window
        if (dq.isNotEmpty() && dq.first() <= i - k) dq.removeFirst()
        // 2. remove smaller values from the back, they can never be the max
        while (dq.isNotEmpty() && nums[dq.last()] < nums[i]) dq.removeLast()
        // 3. add the current index
        dq.addLast(i)
        // 4. the front is the max once the first window is full
        if (i >= k - 1) result[i - k + 1] = nums[dq.first()]
    }
    return result
}
// Time: O(n)   Space: O(k)

fun minSlidingWindow(nums: IntArray, k: Int): IntArray {
    val result = IntArray(nums.size - k + 1)
    val dq = ArrayDeque<Int>()                     // indices, values increasing
    for (i in nums.indices) {
        if (dq.isNotEmpty() && dq.first() <= i - k) dq.removeFirst()
        while (dq.isNotEmpty() && nums[dq.last()] > nums[i]) dq.removeLast()
        dq.addLast(i)
        if (i >= k - 1) result[i - k + 1] = nums[dq.first()]
    }
    return result
}
// Time: O(n)   Space: O(k)

fun longestWithinLimit(nums: IntArray, limit: Int): Int {
    val maxDq = ArrayDeque<Int>()                  // decreasing values (indices)
    val minDq = ArrayDeque<Int>()                  // increasing values (indices)
    var left = 0
    var best = 0
    for (right in nums.indices) {
        while (maxDq.isNotEmpty() && nums[maxDq.last()] < nums[right]) maxDq.removeLast()
        maxDq.addLast(right)
        while (minDq.isNotEmpty() && nums[minDq.last()] > nums[right]) minDq.removeLast()
        minDq.addLast(right)

        // shrink while max - min is too big
        while (nums[maxDq.first()] - nums[minDq.first()] > limit) {
            left++
            if (maxDq.first() < left) maxDq.removeFirst()
            if (minDq.first() < left) minDq.removeFirst()
        }
        best = maxOf(best, right - left + 1)
    }
    return best
}
// Time: O(n)   Space: O(n)

fun longestSubarray(nums: IntArray, limit: Int): Int {
    val maxDq = ArrayDeque<Int>()
    val minDq = ArrayDeque<Int>()
    var left = 0
    var best = 0
    for (right in nums.indices) {
        while (maxDq.isNotEmpty() && nums[maxDq.last()] <= nums[right]) maxDq.removeLast()
        while (minDq.isNotEmpty() && nums[minDq.last()] >= nums[right]) minDq.removeLast()
        maxDq.addLast(right)
        minDq.addLast(right)
        while (nums[maxDq.first()] - nums[minDq.first()] > limit) {
            left++
            if (maxDq.first() < left) maxDq.removeFirst()
            if (minDq.first() < left) minDq.removeFirst()
        }
        best = maxOf(best, right - left + 1)
    }
    return best
}
// Time: O(n)   Space: O(n)

fun shortestSubarray(nums: IntArray, k: Int): Int {
    val n = nums.size
    val prefix = LongArray(n + 1)
    for (i in 0 until n) prefix[i + 1] = prefix[i] + nums[i]

    val dq = ArrayDeque<Int>()                     // indices with increasing prefix sums
    var best = Int.MAX_VALUE
    for (i in 0..n) {
        // front gives the earliest start that satisfies the sum
        while (dq.isNotEmpty() && prefix[i] - prefix[dq.first()] >= k) {
            best = minOf(best, i - dq.removeFirst())
        }
        // keep prefix sums increasing: a larger earlier prefix is never useful
        while (dq.isNotEmpty() && prefix[dq.last()] >= prefix[i]) dq.removeLast()
        dq.addLast(i)
    }
    return if (best == Int.MAX_VALUE) -1 else best
}
// Time: O(n)   Space: O(n)
// Sliding window fails with negatives; prefix sums + monotonic deque works

fun maxResult(nums: IntArray, k: Int): Int {
    val n = nums.size
    val dp = IntArray(n)
    dp[0] = nums[0]
    val dq = ArrayDeque<Int>()                     // indices with decreasing dp values
    dq.addLast(0)
    for (i in 1 until n) {
        if (dq.first() < i - k) dq.removeFirst()   // out of jump range
        dp[i] = nums[i] + dp[dq.first()]           // best previous score in range
        while (dq.isNotEmpty() && dp[dq.last()] <= dp[i]) dq.removeLast()
        dq.addLast(i)
    }
    return dp[n - 1]
}
// Time: O(n)   Space: O(n)
// Replaces an O(n * k) DP with O(n)

fun constrainedSubsetSum(nums: IntArray, k: Int): Int {
    val dp = IntArray(nums.size)
    val dq = ArrayDeque<Int>()                     // decreasing dp values
    var best = Int.MIN_VALUE
    for (i in nums.indices) {
        if (dq.isNotEmpty() && dq.first() < i - k) dq.removeFirst()
        val bestPrev = if (dq.isEmpty()) 0 else maxOf(0, dp[dq.first()])
        dp[i] = nums[i] + bestPrev
        while (dq.isNotEmpty() && dp[dq.last()] <= dp[i]) dq.removeLast()
        dq.addLast(i)
        best = maxOf(best, dp[i])
    }
    return best
}
// Time: O(n)   Space: O(n)

class MonotonicQueue {
    private val dq = ArrayDeque<Int>()

    fun push(value: Int) {
        while (dq.isNotEmpty() && dq.last() < value) dq.removeLast()
        dq.addLast(value)
    }

    fun max(): Int = dq.first()

    fun pop(value: Int) {
        // remove only if the leaving value is the current max
        if (dq.isNotEmpty() && dq.first() == value) dq.removeFirst()
    }
}

fun maxSlidingWindowClass(nums: IntArray, k: Int): IntArray {
    val q = MonotonicQueue()
    val result = IntArray(nums.size - k + 1)
    for (i in nums.indices) {
        q.push(nums[i])
        if (i >= k - 1) {
            result[i - k + 1] = q.max()
            q.pop(nums[i - k + 1])
        }
    }
    return result
}
// Time: O(n)   Space: O(k)
// This value-based version works because equal values are all kept in the deque

// For each window of size k, find (max - min). Use two deques.
fun windowRanges(nums: IntArray, k: Int): IntArray {
    val maxDq = ArrayDeque<Int>()
    val minDq = ArrayDeque<Int>()
    val result = IntArray(nums.size - k + 1)
    for (i in nums.indices) {
        if (maxDq.isNotEmpty() && maxDq.first() <= i - k) maxDq.removeFirst()
        if (minDq.isNotEmpty() && minDq.first() <= i - k) minDq.removeFirst()
        while (maxDq.isNotEmpty() && nums[maxDq.last()] <= nums[i]) maxDq.removeLast()
        while (minDq.isNotEmpty() && nums[minDq.last()] >= nums[i]) minDq.removeLast()
        maxDq.addLast(i)
        minDq.addLast(i)
        if (i >= k - 1) result[i - k + 1] = nums[maxDq.first()] - nums[minDq.first()]
    }
    return result
}
// Time: O(n)   Space: O(k)
